void testIterator()
{
    cxxtools::QueryParams q;
    q.add("p1", "value1");
    q.add("p2", "value2");
    q.add("p2", "value3");
    q.add("value4");
    q.add("value5");

    cxxtools::QueryParams::const_iterator it;

    it = q.begin();
    CXXTOOLS_UNIT_ASSERT(it != q.end());
    CXXTOOLS_UNIT_ASSERT_EQUALS(*it, "value4");
    ++it;
    CXXTOOLS_UNIT_ASSERT(it != q.end());
    CXXTOOLS_UNIT_ASSERT_EQUALS(*it, "value5");
    ++it;
    CXXTOOLS_UNIT_ASSERT(it == q.end());

    it = q.begin("p1");
    CXXTOOLS_UNIT_ASSERT(it != q.end());
    CXXTOOLS_UNIT_ASSERT_EQUALS(*it, "value1");
    ++it;
    CXXTOOLS_UNIT_ASSERT(it == q.end());

    it = q.begin("p2");
    CXXTOOLS_UNIT_ASSERT(it != q.end());
    CXXTOOLS_UNIT_ASSERT_EQUALS(*it, "value2");
    ++it;
    CXXTOOLS_UNIT_ASSERT(it != q.end());
    CXXTOOLS_UNIT_ASSERT_EQUALS(*it, "value3");
    ++it;
    CXXTOOLS_UNIT_ASSERT(it == q.end());
}

_tiffWriteProc(thandle_t hdata, tdata_t buf, tsize_t size) {
    TIFFSTATE *state = (TIFFSTATE *)hdata;
    tsize_t to_write;

    TRACE(("_tiffWriteProc: %d \n", (int)size));
    dump_state(state);

    to_write = min(size, state->size - (tsize_t)state->loc);
    if (state->flrealloc && size > to_write) {
        tdata_t new_data;
        tsize_t newsize = state->size;
        while (newsize < (size + state->size)) {
            if (newsize > INT_MAX - 64 * 1024) {
                return 0;
            }
            newsize += 64 * 1024;
            // newsize*=2; // UNDONE, by 64k chunks?
        }
        TRACE(("Reallocing in write to %d bytes\n", (int)newsize));
        /* malloc check ok, overflow checked above */
        new_data = realloc(state->data, newsize);
        if (!new_data) {
            // fail out
            return 0;
        }
        state->data = new_data;
        state->size = newsize;
        to_write = size;
    }

    TRACE(("to_write: %d\n", (int)to_write));

    _TIFFmemcpy((UINT8 *)state->data + state->loc, buf, to_write);
    state->loc += (toff_t)to_write;
    state->eof = max(state->loc, state->eof);

    dump_state(state);
    return to_write;
}

onlyLettersAhead(const TranslationTableHeader *table, int pos, const InString *input,
		int transCharslen, TranslationTableCharacterAttributes afterAttributes) {
	/* Actullly, spaces, then letters */
	int k;
	if (!(afterAttributes & CTC_Space)) return 0;
	for (k = pos + transCharslen + 1; k < input->length; k++) {
		TranslationTableCharacterAttributes attr =
				(findCharOrDots(input->chars[k], 0, table))->attributes;
		if ((attr & CTC_Space)) continue;
		if ((attr & (CTC_Letter | CTC_LitDigit)))
			return 1;
		else
			return 0;
	}
	return 0;
}

static int bid_standard(struct archive_read* a) {
	const uint8_t* p;

	if(!read_ahead(a, rar5_signature_size, &p))
